create table d_ref_future_properties(key_instrument_id string comment '证券内码-期货代码 ',ename string comment '证券英文简称 ',name string comment '证券中文简称 ',code string comment '交易代码 ',sccode_with_suffix string comment '标准合约代码(带后缀） ',sccode string comment '标准合约代码 ',exchmarket string comment '交易所 字典项=EXCHANGE',listdate string comment '上市日期 ',delistdate string comment '最后交易日期 ',dlmonth string comment '交割月份 ',ltdldate string comment '最后交割日 ',cctype string comment '连续合约类型 ',contract_multiplier string comment '合约乘数 ',created_datetime string comment '创建时间 ',updated_datetime string comment '更新时间 ',data_source string comment 'DATA_SOURCE ',underlying_ins_id string comment '期货标的编码',type string comment '合约类型',price_limit string comment '涨跌幅',future_type string comment '期货类型',data_time string comment '数据时间') partitioned by (busi_date string comment '业务日期') row format delimited fields terminated by ',' stored as textfile;
